tool.command:
mkdir -p out ;
ln -sf "$scan" "$scan.element_identifier" ; ln -sf "$predicted" "$predicted.element_identifier" ;
#if $staticMaskFile: ln -sf "$staticMaskFile" "$staticMaskFile.element_identifier" ; #end if
#set $options = ""
#if $anisotropic: #set $options = $options + " --anisotropic " #end if #if $mosaicFit: #set $options = $options + " --fit-mosaicity " #end if #if $mosaicRadial: #set $options = $options + " --mosaicity-radial " #end if #if $spherical: #set $options = $options + " --shape-spherical " #end if #if $normalized: #set $options = $options + " --shape-fit-normalized " #end if #if $matrix: #set $options = $options + " --matrix-free " #end if #if str($matrixFp) != "": #set $options = $options + " --matrix-free-fp-target " + str($matrixFp) + " " #end if #if $staticMaskFile: #set $options = $options + " --static-mask-file " + str($staticMaskFile.element_identifier) + " " #end if #if $createVisualizations: #set $options = $options + " --create-visualizations " #end if
python -u -m subhkl.io.parser integrator "$scan.element_identifier" $instrument "$predicted.element_identifier" out/integrator.h5 --sigmas $sigma --nominal-sigma $nominalSigma --mosaicity-bound-mrad $mosaicMrad --shape-fit-min-snr $snr --matrix-free-profile $matrixProfile --rel-border-width $relBorder --chunk-size $chunk --show-progress $options && python -u -m subhkl.io.parser mtz-exporter out/integrator.h5 out/reflections.mtz --predictions-file "$predicted.element_identifier"
